class MetricsCalculator:
    POSITIVE = 1
    NEGATIVE = 0

    def __init__(self):
        self._true_positives = 0
        self._false_positives = 0
        self._false_negatives = 0
        self._true_negatives = 0

    @property
    def true_positives(self):
        return self._true_positives

    @property
    def false_positives(self):
        return self._false_positives

    @property
    def false_negatives(self):
        return self._false_negatives

    @property
    def true_negatives(self):
        return self._true_negatives

    def _update_single(self, predicted, true):
        if predicted == self.POSITIVE and true == self.POSITIVE:
            self._true_positives += 1
        elif predicted == self.POSITIVE and true == self.NEGATIVE:
            self._false_positives += 1
        elif predicted == self.NEGATIVE and true == self.POSITIVE:
            self._false_negatives += 1
        elif predicted == self.NEGATIVE and true == self.NEGATIVE:
            self._true_negatives += 1

    def _update(self, predicted_labels, true_labels):
        for predicted, true in zip(predicted_labels, true_labels):
            self._update_single(predicted, true)

    def _precision(self):
        if self._true_positives + self._false_positives == 0:
            return 0.0
        return self._true_positives / (self._true_positives + self._false_positives)

    def _recall(self):
        if self._true_positives + self._false_negatives == 0:
            return 0.0
        return self._true_positives / (self._true_positives + self._false_negatives)

    def precision(self, predicted_labels, true_labels):
        self._update(predicted_labels, true_labels)
        return self._precision()

    def recall(self, predicted_labels, true_labels):
        self._update(predicted_labels, true_labels)
        return self._recall()

    def f1_score(self, predicted_labels, true_labels):
        self._update(predicted_labels, true_labels)
        precision = self._precision()
        recall = self._recall()
        if precision + recall == 0.0:
            return 0.0
        return (2 * precision * recall) / (precision + recall)

    def accuracy(self, predicted_labels, true_labels):
        self._update(predicted_labels, true_labels)
        total = self._true_positives + self._true_negatives + self._false_positives + self._false_negatives
        if total == 0:
            return 0.0
        return (self._true_positives + self._true_negatives) / total
